function validate([tokens, power]) {
  if (tokens.length > 1000) return 'tokens holds at most 1000 values.';
  if (tokens.some(v => !Number.isInteger(v) || v < 0 || v >= 10000)) return 'Each token is an integer from 0 to 9999.';
  if (!Number.isInteger(power) || power < 0 || power >= 10000) return 'power is an integer from 0 to 9999.';
  return null;
}

