function bagOfTokensScore(tokens, power) {
  tokens.sort((a, b) => a - b);
  let left = 0;
  let right = tokens.length - 1;
  let score = 0;
  let best = 0;

  while (left <= right) {
    if (power >= tokens[left]) {
      power -= tokens[left];
      left++;
      score++;
      best = Math.max(best, score);
    } else if (score > 0) {
      power += tokens[right];
      right--;
      score--;
    } else {
      break;
    }
  }
  return best;
}

