function bagOfTokensScore(tokens, power) {
  // Explore every state (each token unused, face-up or face-down) reachable by legal moves.
  const n = tokens.length;
  const state = new Array(n).fill('.');
  const seen = new Set();
  let best = 0;
  const visit = (energy, score) => {
    const id = state.join('');
    if (seen.has(id)) return;
    seen.add(id);
    if (score > best) best = score;
    for (let i = 0; i < n; i++) {
      if (state[i] !== '.') continue;
      if (energy >= tokens[i]) { state[i] = 'u'; visit(energy - tokens[i], score + 1); state[i] = '.'; }
      if (score >= 1) { state[i] = 'd'; visit(energy + tokens[i], score - 1); state[i] = '.'; }
    }
  };
  visit(power, 0);
  return best;
}

