function generate(rand, size) {
  if (size === 'large') {
    const n = 800 + Math.floor(rand() * 201);
    const top = [10000, 3000, 500][Math.floor(rand() * 3)];
    return [Array.from({ length: n }, () => Math.floor(rand() * top)), Math.floor(rand() * 10000)];
  }
  const n = Math.floor(rand() * 9);
  const top = [5, 30, 100][Math.floor(rand() * 3)];
  return [Array.from({ length: n }, () => Math.floor(rand() * top)), Math.floor(rand() * (top + 10))];
}
